	protected String letters(int n) {
		StringBuilder sb = new StringBuilder();
		for (int x = Math.max(n, 1); x > 0; x /= 26) {
			x--;
			sb.insert(0, (char) ('a' + x % 26));
		}
		return sb.toString();
	}

